1	/* ================================================================
2	   城市浮生记 (City Life Story) — 全局样式
3	   设计参考: Notion Light + Kindle Green Mode + Zen Garden
4	   主题: 鲜亮绿色护眼 — 奶油白底色 + 鼠尾草绿强调，减少暗沉，长时间游玩不疲劳
5	   文字配色参考（眼舒适度权威研究）:
6	   - Material Design 3 — on-surface 色阶系统 (1C1B1F → 49454F)
7	   - Solarized — 柔和暖灰调，16色调色板减少视网膜疲劳
8	   - iA Writer / Bear — 专业写作工具的低刺激文字色
9	   - WCAG 2.1 AA — 正文 ≥4.5:1、大文字 ≥3:1 对比度（在 #f5f1e8 背景上精确校准）
10	   - GitHub Primer / Linear / Notion — 现代 SaaS 的阅读舒适配色
11	   ================================================================ */
12	
13	/* ====== CSS 变量 / 主题 (鲜亮绿色护眼 + 柔和文字) ====== */
14	:root {
15	  --bg-primary: #f5f1e8;
16	  --bg-secondary: #faf7f0;
17	  --bg-card: #ffffff;
18	  --bg-card-hover: #f0f7f0;
19	  --bg-sidebar: #faf7f0;
20	  --bg-input: #f0ede4;
21	
22	  --border: #d8d5c8;
23	  --border-light: #c5d5c0;
24	
25	  /* 文字颜色 — 在奶油白 (#f5f1e8) 背景上精确校准:
26	     --text-primary:   ~7.2:1 对比度（正文阅读最优，柔和但不疲劳）
27	     --text-secondary: ~4.8:1 对比度（次级信息，减轻视觉重量）
28	     --text-muted:     ~3.2:1 对比度（辅助/提示文字，低视觉优先级）
29	     色调选择暖灰而非冷黑 — 暖色调减少蓝光刺激，长时间阅读更舒适 */
30	  --text-primary: #3d3a35;
31	  --text-secondary: #6b6760;
32	  --text-muted: #99958e;
33	
34	  --accent: #4a9e5c;
35	  --accent-glow: rgba(74, 158, 92, 0.12);
36	  --accent-hover: #3a8048;
37	
38	  --success: #4a9e5c;
39	  --success-bg: rgba(74, 158, 92, 0.1);
40	  --danger: #c4553d;
41	  --danger-bg: rgba(196, 85, 61, 0.08);
42	  --warning: #c49a3a;
43	  --warning-bg: rgba(196, 154, 58, 0.1);
44	  --info: #5a8ab4;
45	
46	  /* 属性条颜色 — 降低饱和度，柔和不刺眼 */
47	  --hair-color: #7ab8d8;
48	  --mental-color: #b8a0d4;
49	  --kpi-color: #d4a840;
50	  --risk-color: #c4553d;
51	  --physique-color: #c4803a;
52	  --intelligence-color: #5a8ab4;
53	  --agility-color: #5aaa5a;
54	  --mental-attrs-color: #9b74b8;
55	
56	  --font-mono: "Consolas", "Courier New", monospace;
57	  --font-sans:
58	    -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC",
59	    "Microsoft YaHei", sans-serif;
60	
61	  --radius-sm: 4px;
62	  --radius-md: 8px;
63	  --radius-lg: 12px;
64	  --radius-xl: 16px;
65	
66	  --sidebar-width: 280px;
67	  --header-height: 48px;
68	  --transition: 0.2s ease;
69	}
70	
71	/* ====== Reset ====== */
72	*,
73	*::before,
74	*::after {
75	  box-sizing: border-box;
76	  margin: 0;
77	  padding: 0;
78	}
79	
80	html,
81	body {
82	  height: 100%;
83	  overflow: hidden;
84	}
85	
86	body {
87	  font-family: var(--font-sans);
88	  font-size: 14px;
89	  line-height: 1.5;
90	  color: var(--text-primary);
91	  background: var(--bg-primary);
92	  -webkit-font-smoothing: antialiased;
93	}
94	
95	/* ====== Scrollbar ====== */
96	::-webkit-scrollbar {
97	  width: 6px;
98	  height: 6px;
99	}
100	::-webkit-scrollbar-track {
101	  background: transparent;
102	}
103	::-webkit-scrollbar-thumb {
104	  background: var(--border-light);
105	  border-radius: 3px;
106	}
107	::-webkit-scrollbar-thumb:hover {
108	  background: var(--text-muted);
109	}
110	
111	/* ====== App Layout (CSS Grid) ====== */
112	#app {
113	  display: grid;
114	  grid-template-rows: var(--header-height) 1fr;
115	  grid-template-columns: var(--sidebar-width) 1fr;
116	  grid-template-areas:
117	    "header header"
118	    "sidebar main";
119	  height: 100vh;
120	  max-height: 100vh;
121	}
122	
123	/* ====== Header ====== */
124	#header {
125	  grid-area: header;
126	  display: flex;
127	  align-items: center;
128	  justify-content: space-between;
129	  padding: 0 16px;
130	  background: var(--bg-secondary);
131	  border-bottom: 1px solid var(--border);
132	  z-index: 100;
133	}
134	
135	.header-left {
136	  display: flex;
137	  align-items: center;
138	  gap: 12px;
139	}
140	
141	.header-logo {
142	  font-size: 18px;
143	  font-weight: 700;
144	  color: var(--accent);
145	  letter-spacing: 0.5px;
146	}
147	
148	.header-logo span {
149	  color: var(--text-secondary);
150	  font-size: 12px;
151	  font-weight: 400;
152	  margin-left: 6px;
153	}
154	
155	.header-stats {
156	  display: flex;
157	  align-items: center;
158	  gap: 20px;
159	  font-size: 13px;
160	}
161	
162	.header-stat {
163	  display: flex;
164	  align-items: center;
165	  gap: 6px;
166	}
167	
168	.header-stat .label {
169	  color: var(--text-muted);
170	  font-size: 11px;
171	}
172	
173	.header-stat .value {
174	  color: var(--text-primary);
175	  font-weight: 600;
176	}
177	
178	.header-stat .value.cash {
179	  color: var(--success);
180	}
181	
182	.header-stat .value.debt {
183	  color: var(--danger);
184	  font-weight: 700;
185	}
186	
187	/* 单债务闪烁（只有一种债务时，沉稳的红色呼吸闪烁） */
188	.header-stat .value.debt.single-debt-blink {
189	  animation: debt-blink 1.2s ease-in-out infinite;
190	}
191	
192	/* 多债务轮播项的闪烁（轮播到当前项时闪烁） */
193	.header-stat .value.debt.carousel-debt-blink {
194	  animation: debt-blink 0.9s ease-in-out infinite;
195	}
196	
197	/* 债务区域背景闪烁（有债务时整块区域有微弱红光提醒） */
198	.header-debt-active {
199	  border: 1px solid rgba(196, 85, 61, 0.25) !important;
200	  border-radius: 6px !important;
201	  padding: 0 8px !important;
202	  background: rgba(196, 85, 61, 0.06) !important;
203	  animation: debt-pulse-bg 2s ease-in-out infinite;
204	}
205	
