  align-items: center;
  padding: 6px 10px;
  border-bottom: 1px solid var(--border-light);
  font-size: 13px;
}
.compare-row:last-child {
  border-bottom: none;
}
.compare-label {
  color: var(--text-secondary);
  font-weight: 500;
}
.compare-same {
  color: var(--text-primary);
  font-weight: 600;
}
.compare-val {
  font-weight: 600;
}
.compare-val.old {
  color: var(--text-muted);
}
.compare-val.new {
  min-width: 80px;
  text-align: center;
}
.compare-gain {
  color: var(--success) !important;
}
.compare-loss {
  color: var(--danger) !important;
}
.compare-arrow {
  color: var(--text-muted);
  font-size: 12px;
  width: 20px;
  text-align: center;
}
.compare-diff {
  font-size: 11px;
  margin-left: 8px;
}
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* 低行动力闪烁警告 */
@keyframes ap-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}
@keyframes ap-blink-border {
  0%,
  100% {
    box-shadow: 0 0 12px rgba(255, 152, 0, 0.4);
  }
  50% {
    box-shadow: 0 0 24px rgba(255, 152, 0, 0.8);
  }
}

/* ====== 📖 百科 Wiki Tab ====== */
.wiki-tab {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.wiki-header h2 {
  font-size: 18px;
  color: var(--accent);
}
.wiki-search {
  display: flex;
  gap: 8px;
  margin-top: 8px;
}
.wiki-search input {
  flex: 1;
  padding: 8px 12px;
  border: 1px solid #d8d3c5;
  border-radius: 8px;
  background: #fff;
  color: var(--text-primary);
  font-size: 13px;
  font-family: var(--font-sans);
}
.wiki-search input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 2px rgba(74, 158, 92, 0.2);
}
.wiki-clear {
  padding: 8px 12px;
  background: #fff;
  border: 1px solid #d8d3c5;
  border-radius: 8px;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 12px;
}
.wiki-clear:hover {
  border-color: var(--danger);
  color: var(--danger);
}

.wiki-layout {
  display: grid;
  grid-template-columns: 180px 1fr;
  gap: 16px;
  align-items: start;
}
.wiki-nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
  background: #ffffff;
  border: 1px solid #e6e0d0;
  border-radius: 10px;
  padding: 8px;
  position: sticky;
  top: 0;
}
.wiki-nav-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  background: transparent;
  border: none;
  border-radius: 6px;
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 12px;
  text-align: left;
  transition: all 0.15s;
  font-family: var(--font-sans);
}
.wiki-nav-btn:hover {
  background: #f5f1e8;
  color: var(--text-primary);
}
.wiki-nav-btn.active {
  background: rgba(74, 158, 92, 0.12);
  color: var(--accent);
  font-weight: 600;
}
.wiki-nav-ico {
  font-size: 14px;
  width: 18px;
  text-align: center;
}
.wiki-nav-name {
  flex: 1;
}
.wiki-nav-count {
  font-size: 10px;
  color: var(--text-muted);
  background: #f5f1e8;
  border-radius: 8px;
  padding: 1px 6px;
  min-width: 22px;
  text-align: center;
}
.wiki-nav-btn.active .wiki-nav-count {
  background: rgba(74, 158, 92, 0.2);
  color: var(--accent);
}

.wiki-content {
  background: #ffffff;
  border: 1px solid #e6e0d0;
  border-radius: 10px;
  padding: 16px;
  min-height: 300px;
}
.wiki-list-header h3 {
  margin: 0 0 12px;
  font-size: 16px;
  color: var(--text-primary);
}
.wiki-count {
  font-size: 12px;
  color: var(--text-muted);
  font-weight: normal;
}
.wiki-empty {
  color: var(--text-muted);
  text-align: center;
  padding: 40px;
}
.wiki-entries {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 10px;
}
.wiki-card {
  background: #fdfaf3;
  border: 1px solid #e6e0d0;
  border-radius: 8px;
  padding: 10px 12px;
  cursor: pointer;
  transition: all 0.15s;
}
.wiki-card:hover {
  border-color: var(--accent);
  background: #fff;
  transform: translateY(-1px);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05);
}
.wiki-card-head {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
}
.wiki-card-head h4 {
  margin: 0;
  font-size: 13px;
  color: var(--text-primary);
  flex: 1;
}
.wiki-card-ico {
  font-size: 16px;
}
.wiki-card-brief {
  margin: 0;
  font-size: 11px;
  color: var(--text-muted);
  line-height: 1.5;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.wiki-badge {
  font-size: 10px;
  padding: 2px 6px;
  border-radius: 6px;
  font-weight: 600;
  white-space: nowrap;
}
.wiki-badge.ok {
  background: rgba(74, 158, 92, 0.15);
  color: var(--accent);
}
.wiki-badge.warn {
  background: rgba(212, 160, 23, 0.15);
  color: #b08712;
}
.wiki-badge.info {
  background: rgba(52, 152, 219, 0.15);
  color: #2575b3;
}
.wiki-badge.bad {
  background: rgba(231, 76, 60, 0.15);
  color: var(--danger);
}
.wiki-badge.muted {
  background: #f0ebde;
  color: var(--text-muted);
}

/* 详情视图 */
.wiki-detail {
  position: relative;
}
.wiki-back {
  background: #f5f1e8;
  border: 1px solid #d8d3c5;
  border-radius: 6px;
  padding: 6px 12px;
  font-size: 12px;
  color: var(--text-secondary);
  cursor: pointer;
  margin-bottom: 12px;
}
.wiki-back:hover {
  border-color: var(--accent);
  color: var(--accent);
}
.wiki-detail-body h2 {
  font-size: 18px;
  margin: 0 0 8px;
  color: var(--text-primary);
}
.wiki-detail-body h3 {
  font-size: 14px;
  margin: 16px 0 8px;
  color: var(--accent);
  border-bottom: 1px solid #ece7d8;
  padding-bottom: 4px;
}
.wiki-detail-body p,
.wiki-detail-body ul,
.wiki-detail-body ol {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.7;
}
.wiki-detail-body code {
  background: #f5f1e8;
  border-radius: 3px;
  padding: 1px 4px;
  font-family: var(--font-mono, monospace);
  font-size: 11px;
}
.wiki-desc {
  font-size: 13px !important;
  color: var(--text-secondary);
  margin: 0 0 12px;
  font-style: italic;
}
.wiki-attrs {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 8px;
  background: #fdfaf3;
  border-radius: 8px;
  padding: 10px;
  margin-bottom: 12px;
}
.wiki-attrs > div {
  font-size: 12px;
  color: var(--text-secondary);
}
.wiki-attrs b {
  color: var(--text-primary);
  margin-right: 6px;
}
.wiki-list {
  margin: 0 0 12px 16px;
  padding: 0;
}
.wiki-list li {
  margin-bottom: 4px;
}
.wiki-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  margin: 8px 0 12px;
}
.wiki-table th,
.wiki-table td {
  padding: 6px 8px;
  border: 1px solid #ece7d8;
  text-align: left;
  color: var(--text-secondary);
}
.wiki-table th {
  background: #fdfaf3;
  color: var(--text-primary);
  font-weight: 600;
}
.wiki-table tr:nth-child(even) td {
  background: #fdfaf3;
}
.wiki-link {
  color: var(--accent);
  text-decoration: none;
  font-weight: 500;
  border-bottom: 1px dashed rgba(74, 158, 92, 0.4);
  cursor: pointer;
}
.wiki-link:hover {
  border-bottom-style: solid;
  background: rgba(74, 158, 92, 0.06);
}
.wiki-links {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
}
.wiki-links .wiki-link {
  background: #fdfaf3;
  border: 1px solid #e6e0d0;
  border-radius: 14px;
  padding: 4px 10px;
  border-bottom: 1px solid #e6e0d0;
  font-size: 11px;
}
.wiki-links .wiki-link:hover {
  border-color: var(--accent);
  background: rgba(74, 158, 92, 0.08);
}
.wiki-tip {
  background: rgba(74, 158, 92, 0.06);
  border-left: 3px solid var(--accent);
  padding: 8px 10px;
  border-radius: 0 6px 6px 0;
  font-size: 12px !important;
  color: var(--text-secondary);
  margin: 8px 0 12px;
}
.wiki-quote {
  background: #fdfaf3;
  border-left: 3px solid #d4a017;
  padding: 8px 10px;
  border-radius: 0 6px 6px 0;
  font-size: 12px !important;
  color: var(--text-secondary);
  font-style: italic;
  margin: 8px 0;
}
.wiki-pill {
  display: inline-block;
  background: #f5f1e8;
  border: 1px solid #e6e0d0;
  border-radius: 12px;
  padding: 2px 10px;
  font-size: 11px;
  color: var(--text-secondary);
}

/* 移动端适配 */
@media (max-width: 760px) {
  .wiki-layout {
    grid-template-columns: 1fr;
  }
  .wiki-nav {
    flex-direction: row;
    overflow-x: auto;
    position: relative;
  }
  .wiki-nav-btn {
    flex: 0 0 auto;
    flex-direction: column;
    padding: 6px 8px;
    min-width: 60px;
    text-align: center;
  }
  .wiki-nav-btn .wiki-nav-name {
    font-size: 10px;
  }
  .wiki-nav-btn .wiki-nav-count {
    font-size: 9px;
    padding: 0 4px;
  }
  .wiki-entries {
    grid-template-columns: 1fr;
  }
}

/* ====== 春节事件弹窗专属样式 ====== */
.spring-fest-modal .modal-box {
  border: 2px solid rgba(231, 76, 60, 0.5);
  background: linear-gradient(180deg, rgba(196, 85, 61, 0.08), var(--bg-secondary));
  border-top: 4px solid #e74c3c;
}

.spring-fest-modal .event-header {
  border-bottom-color: rgba(231, 76, 60, 0.3);
}

.spring-fest-modal .event-icon {
  background: radial-gradient(circle, rgba(231, 76, 60, 0.2), transparent);
}

.spring-fest-modal .event-title {
  color: #e74c3c;
}

/* 春节进度指示器 */
.spring-fest-progress {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-bottom: 12px;
  padding: 6px 12px;
  background: rgba(231, 76, 60, 0.06);
  border-radius: 20px;
}

.spring-fest-progress-label {
  font-size: 10px;
  color: #e74c3c;
  font-weight: 600;
  letter-spacing: 1px;
}

.spring-fest-progress-dots {
  display: flex;
  gap: 4px;
}

.spring-fest-progress-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(231, 76, 60, 0.2);
  transition: all 0.3s ease;
}

.spring-fest-progress-dot.active {
  background: #e74c3c;
  box-shadow: 0 0 6px rgba(231, 76, 60, 0.6);
}

.spring-fest-progress-dot.passed {
  background: #c0392b;
}

/* 春节选项按钮增强 */
.spring-fest-modal .event-choice {
  border-color: rgba(231, 76, 60, 0.15);
}

.spring-fest-modal .event-choice:hover:not(.disabled) {
  border-color: #e74c3c;
  background: linear-gradient(90deg, rgba(231, 76, 60, 0.08), var(--bg-card-hover));
}

.spring-fest-modal .event-choice .choice-main {
  color: #e74c3c;
}

/* 春节装饰元素 */
.spring-fest-decor {
  position: absolute;
  font-size: 14px;
  opacity: 0.15;
  pointer-events: none;
  animation: springFestFloat 3s ease-in-out infinite;
}

.spring-fest-decor.lantern-left {
  top: 10px;
  left: 10px;
}

.spring-fest-decor.lantern-right {
  top: 10px;
  right: 10px;
  animation-delay: 0.5s;
}

.spring-fest-decor.coin-bottom {
  bottom: 10px;
  right: 15px;
  animation-delay: 1s;
}

@keyframes springFestFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-4px); }
}

/* 春节弹窗入场动画增强 */
.spring-fest-modal .modal-box {
  animation: springFestPop 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes springFestPop {
  0% {
    transform: scale(0.8) translateY(-30px);
    opacity: 0;
  }
  100% {
    transform: scale(1) translateY(0);
    opacity: 1;
  }
}

/* 春节事件故事文本高亮关键词 */
.spring-fest-story .highlight {
  color: #e74c3c;
  font-weight: 600;
}

/* ====== 公司历史书弹窗样式 ====== */
.company-history-modal .modal-box {
  max-width: 720px;
  min-width: 500px;
  max-height: 85vh;
  overflow-y: auto;
  border-top: 4px solid #4a9e5c;
  background: linear-gradient(180deg, rgba(74, 158, 92, 0.06), var(--bg-secondary));
}

.company-history-modal .modal-box::-webkit-scrollbar {
  width: 6px;
}

.company-history-modal .modal-box::-webkit-scrollbar-thumb {
  background: rgba(74, 158, 92, 0.3);
  border-radius: 3px;
}

/* 头部 */
.ch-title-area {
  display: flex;
  align-items: center;
  gap: 12px;
}

.ch-icon {
  font-size: 48px;
  width: 64px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle, rgba(74, 158, 92, 0.15), transparent);
  border-radius: 12px;
}

.ch-titles {
  flex: 1;
}

.ch-name {
  font-size: 20px;
  color: var(--text-primary);
  margin: 0 0 4px 0;
}

.ch-meta {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}

.ch-industry {
  font-size: 11px;
  color: var(--text-muted);
  background: var(--bg-input);
  padding: 2px 8px;
  border-radius: 10px;
}

.ch-status {
  font-size: 10px;
  padding: 2px 8px;
  border-radius: 10px;
  font-weight: 600;
}

.ch-status.ipo {
  background: rgba(76, 175, 80, 0.15);
  color: #4caf50;
}

.ch-status.ceased {
  background: rgba(231, 76, 60, 0.15);
  color: #e74c3c;
}

.ch-close {
  background: none;
  border: none;
  font-size: 18px;
  color: var(--text-muted);
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 4px;
  transition: all 0.15s;
}

.ch-close:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text-primary);
}

/* 通用区块 */
.ch-section {
  margin-top: 16px;
  padding-top: 12px;
  border-top: 1px solid var(--border);
}

.ch-section:first-of-type {
  margin-top: 12px;
}

.ch-section-title {
  font-size: 13px;
  color: var(--text-primary);
  margin: 0 0 10px 0;
  font-weight: 600;
}

/* 基本信息 */
.ch-basic-info {
  background: rgba(74, 158, 92, 0.04);
  border-radius: 8px;
  padding: 10px 14px;
}

.ch-info-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 4px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.03);
}

.ch-info-row:last-child {
  border-bottom: none;
}

.ch-label {
  font-size: 12px;
  color: var(--text-muted);
}

.ch-value {
  font-size: 12px;
  color: var(--text-primary);
  font-weight: 500;
  text-align: right;
  max-width: 60%;
}

.ch-bio {
  font-style: italic;
  color: var(--text-secondary);
}

/* 当前状态 */
.ch-status-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.ch-stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.ch-stat-label {
  font-size: 11px;
  color: var(--text-muted);
}

.ch-stat-value {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
}

.ch-stat-bar {
  height: 6px;
  background: var(--bg-input);
  border-radius: 3px;
  overflow: hidden;
}

.ch-stat-fill {
  height: 100%;
  background: linear-gradient(90deg, #4a9e5c, #66bb6a);
  border-radius: 3px;
  transition: width 0.3s ease;
}

/* 时间线 */
.ch-timeline {
  position: relative;
  padding-left: 24px;
}

.ch-timeline::before {
  content: "";
  position: absolute;
  left: 6px;
  top: 0;
  bottom: 0;
  width: 2px;
  background: linear-gradient(180deg, rgba(74, 158, 92, 0.3), rgba(74, 158, 92, 0.05));
}

.ch-timeline-item {
  position: relative;
  padding: 8px 0 8px 16px;
}

.ch-timeline-dot {
  position: absolute;
  left: -22px;
  top: 6px;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg-card);
  border: 2px solid rgba(74, 158, 92, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  z-index: 1;
}

/* 里程碑颜色分类 */
.ch-milestone-ipo .ch-timeline-dot {
  border-color: #4caf50;
  background: rgba(76, 175, 80, 0.15);
  box-shadow: 0 0 8px rgba(76, 175, 80, 0.4);
}

.ch-milestone-death .ch-timeline-dot {
  border-color: #e74c3c;
  background: rgba(231, 76, 60, 0.15);
  box-shadow: 0 0 8px rgba(231, 76, 60, 0.4);
}

.ch-milestone-merge .ch-timeline-dot {
  border-color: #ff9800;
  background: rgba(255, 152, 0, 0.15);
  box-shadow: 0 0 8px rgba(255, 152, 0, 0.4);
}

.ch-timeline-day {
  font-size: 10px;
  color: var(--text-muted);
  margin-bottom: 2px;
}

.ch-timeline-desc {
  font-size: 12px;
  color: var(--text-primary);
}

/* 事件记录 */
.ch-events-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 200px;
  overflow-y: auto;
  padding: 4px;
}

.ch-events-list::-webkit-scrollbar {
  width: 4px;
}

.ch-events-list::-webkit-scrollbar-thumb {
  background: rgba(74, 158, 92, 0.2);
  border-radius: 2px;
}

.ch-event-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  background: var(--bg-input);
  border-radius: 6px;
  font-size: 12px;
}

.ch-event-day {
  font-size: 10px;
  color: var(--text-muted);
  font-weight: 600;
  min-width: 36px;
}

.ch-event-icon {
  font-size: 14px;
  min-width: 18px;
}

.ch-event-desc {
  color: var(--text-primary);
  flex: 1;
}

/* 事件颜色分类 */
.ch-event-ipo {
  border-left: 3px solid #4caf50;
}

.ch-event-crisis {
  border-left: 3px solid #e74c3c;
  background: rgba(231, 76, 60, 0.05);
}

.ch-event-merge {
  border-left: 3px solid #ff9800;
}

/* 空状态 */
.ch-empty {
  text-align: center;
  color: var(--text-muted);
  font-style: italic;
  padding: 16px;
  font-size: 12px;
}

/* 弹窗入场动画 */
.company-history-modal .modal-box {
  animation: companyHistoryPop 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes companyHistoryPop {
  0% {
    transform: scale(0.85) translateY(-20px);
    opacity: 0;
  }
  100% {
    transform: scale(1) translateY(0);
    opacity: 1;
  }
}

/* 企业 Tab 中的"查看历史书"按钮 */
.ch-history-btn {
  width: 100%;
  margin-top: 10px;
  padding: 8px 12px;
  background: linear-gradient(90deg, rgba(74, 158, 92, 0.1), rgba(74, 158, 92, 0.05));
  border: 1px solid rgba(74, 158, 92, 0.25);
  border-radius: 6px;
  color: var(--accent);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s ease;
  text-align: center;
}

.ch-history-btn:hover {
  background: linear-gradient(90deg, rgba(74, 158, 92, 0.18), rgba(74, 158, 92, 0.1));
  border-color: var(--accent);
  transform: translateY(-1px);
}

.ch-history-btn:active {
  transform: translateY(0);
}

/* CEO 人格化档案样式 */
.ch-ceo-profile {
  margin: 16px 0;
  padding: 16px;
  background: linear-gradient(135deg, rgba(124, 58, 237, 0.06), rgba(124, 58, 237, 0.02));
  border-radius: 8px;
  border: 1px solid rgba(124, 58, 237, 0.15);
}

.ch-ceo-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 12px;
}

.ch-ceo-main {
  padding: 12px;
  background: rgba(255, 255, 255, 0.4);
  border-radius: 6px;
}

.ch-ceo-header {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 10px;
}

.ch-ceo-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: linear-gradient(135deg, #7c3aed, #a78bfa);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  flex-shrink: 0;
}

.ch-ceo-age {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.8);
  background: rgba(0, 0, 0, 0.2);
  padding: 2px 6px;
  border-radius: 10px;
  margin-top: 4px;
}

.ch-ceo-info {
  flex: 1;
}

.ch-ceo-bg {
  font-size: 12px;
  color: var(--text-secondary);
  margin-bottom: 4px;
}

.ch-ceo-personality {
  font-size: 12px;
  color: var(--text-primary);
  font-style: italic;
}

.ch-ceo-story {
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-secondary);
  margin: 8px 0;
}

.ch-ceo-quote {
  font-size: 12px;
  font-style: italic;
  color: #7c3aed;
  padding: 8px 12px;
  background: rgba(124, 58, 237, 0.08);
  border-radius: 4px;
  border-left: 3px solid #7c3aed;
  margin-top: 8px;
}

.ch-ceo-weakness {
  padding: 12px;
  background: rgba(239, 68, 68, 0.06);
  border-radius: 6px;
  border: 1px solid rgba(239, 68, 68, 0.15);
}

.ch-ceo-weakness p {
  margin: 6px 0 0;
  font-size: 12px;
  color: var(--text-secondary);
}

/* ====== 模式选择 ====== */
.mode-grid {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
  max-width: 600px;
  margin: 0 auto;
}

.mode-card {
  background: var(--bg-card);
  border: 2px solid var(--border);
  border-radius: 12px;
  padding: 20px 16px;
  width: 170px;
  cursor: pointer;
  transition: all 0.2s ease;
  text-align: center;
}

.mode-card:hover {
  border-color: var(--accent);
  transform: translateY(-3px);
  box-shadow: 0 6px 20px rgba(74, 158, 92, 0.15);
}

.mode-card-icon {
  font-size: 36px;
  margin-bottom: 8px;
}

.mode-card-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 6px;
}

.mode-card-brief {
  font-size: 12px;
  color: var(--text-secondary);
  margin-bottom: 6px;
}

.mode-card-diff {
  font-size: 11px;
  color: var(--text-muted);
}

/* 剧本卡片网格 */
.scenario-grid {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-width: 520px;
  margin: 0 auto;
  text-align: left;
}

.scenario-card {
  background: var(--bg-card);
  border: 2px solid var(--border);
  border-radius: 10px;
  padding: 14px 16px;
  cursor: pointer;
  transition: all 0.2s ease;
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.scenario-card:hover {
  border-color: var(--accent);
  transform: translateX(3px);
  box-shadow: 0 3px 12px rgba(74, 158, 92, 0.10);
}

.scenario-card-icon {
  font-size: 30px;
  flex-shrink: 0;
  line-height: 1;
}

.scenario-card-body {
  flex: 1;
  min-width: 0;
}

.scenario-card-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.scenario-card-brief {
  font-size: 12px;
  color: var(--text-secondary);
  margin-top: 3px;
  line-height: 1.5;
}

.scenario-card-tags {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  margin-top: 5px;
}

.scenario-card-tag {
  font-size: 10px;
  padding: 2px 7px;
  border-radius: 4px;
  background: rgba(74, 158, 92, 0.08);
  color: var(--accent);
  border: 1px solid rgba(74, 158, 92, 0.15);
}

.scenario-card-diff {
  font-size: 11px;
  color: var(--text-muted);
  white-space: nowrap;
}

/* 沙盒配置 */
.sandbox-section {
  margin-bottom: 14px;
  padding: 10px 12px;
  background: var(--bg-card);
  border-radius: 8px;
  border: 1px solid var(--border);
}

.sandbox-section-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.sandbox-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 5px;
  font-size: 12px;
}

.sandbox-row label {
  width: 70px;
  flex-shrink: 0;
  color: var(--text-secondary);
  font-size: 12px;
}

.sandbox-row input[type="range"] {
  flex: 1;
  max-width: 180px;
  height: 4px;
  -webkit-appearance: none;
  appearance: none;
  background: var(--border);
  border-radius: 2px;
  outline: none;
}

.sandbox-row input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--accent);
  cursor: pointer;
  border: 2px solid var(--bg-card);
}

.sandbox-row input[type="range"]::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--accent);
  cursor: pointer;
  border: 2px solid var(--bg-card);
}

.sandbox-row .sandbox-val {
  width: 40px;
  text-align: right;
  font-weight: 600;
  color: var(--text-primary);
  font-size: 12px;
}

.sandbox-points-left {
  font-size: 12px;
  color: var(--accent);
  font-weight: 600;
  margin-left: auto;
}

.sandbox-summary {
  font-size: 12px;
  color: var(--text-secondary);
  padding: 8px 12px;
  background: rgba(74, 158, 92, 0.06);
  border-radius: 6px;
  margin-top: 6px;
  line-height: 1.6;
}

.sandbox-select {
  padding: 4px 8px;
  border: 1px solid var(--border);
  border-radius: 4px;
  background: var(--bg-input);
  color: var(--text-primary);
  font-size: 12px;
  outline: none;
}

.sandbox-select:focus {
  border-color: var(--accent);
}

/* 剧本详情弹窗 */
.scenario-detail-icon { font-size: 48px; text-align: center; margin-bottom: 8px; }
.scenario-detail-name { font-size: 20px; font-weight: 700; text-align: center; margin-bottom: 4px; }
.scenario-detail-diff { text-align: center; font-size: 12px; color: var(--text-muted); margin-bottom: 12px; }
.scenario-detail-desc { font-size: 13px; color: var(--text-secondary); line-height: 1.7; margin-bottom: 12px; padding: 0 8px; }
.scenario-detail-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 16px; font-size: 12px; margin-bottom: 12px; }
.scenario-detail-stat { display: flex; justify-content: space-between; padding: 3px 0; border-bottom: 1px solid var(--border); }
.scenario-detail-stat-label { color: var(--text-secondary); }
.scenario-detail-stat-val { font-weight: 600; color: var(--text-primary); }
.scenario-detail-start { font-size: 11px; color: var(--text-muted); font-style: italic; margin-top: 8px; }

/* ====== 创业系统 UI 样式 ====== */

/* 收购要约弹窗 */
.acquisition-modal .modal-box {
  max-width: 600px;
  border-top: 4px solid #2ecc71;
}

.acquisition-stat {
  padding: 10px;
  background: var(--bg-card);
  border-radius: 6px;
  text-align: center;
}

.acquisition-stat-label {
  font-size: 10px;
  color: var(--text-muted);
  margin-bottom: 4px;
}

.acquisition-stat-value {
  font-size: 14px;
  font-weight: bold;
  color: var(--text-primary);
}

/* 市场推广渠道选择 */
.marketing-channel {
  padding: 10px;
  background: var(--bg-card);
  border-radius: 6px;
  border: 1px solid var(--border);
  cursor: pointer;
  transition: all 0.2s;
}

.marketing-channel:hover {
  border-color: var(--accent);
  background: var(--bg-secondary);
}

.marketing-channel.selected {
  border-color: var(--accent);
  background: rgba(74, 158, 92, 0.08);
}

/* 投资人关系度 */
.investor-relationship-bar {
  height: 6px;
  background: var(--bg-input);
  border-radius: 3px;
  overflow: hidden;
  margin-top: 4px;
}

.investor-relationship-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.3s;
}

/* 团队管理 */
.team-management-action {
  padding: 10px;
  background: var(--bg-card);
  border-radius: 6px;
  border: 1px solid var(--border);
  margin-bottom: 6px;
}

.team-management-action:hover {
  border-color: var(--accent);
}

/* 财报弹窗 */
.financial-report-modal .modal-box {
  max-width: 640px;
  border-top: 4px solid #3498db;
}

.financial-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.financial-table th {
  text-align: left;
  padding: 8px;
  background: var(--bg-secondary);
  border-bottom: 2px solid var(--border);
}

.financial-table td {
  padding: 8px;
  border-bottom: 1px solid var(--border);
}

.financial-table tr:hover {
  background: rgba(74, 158, 92, 0.04);
}

/* 员工满意度 */
.employee-satisfaction-bar {
  height: 4px;
  background: var(--bg-input);
  border-radius: 2px;
  overflow: hidden;
  margin-top: 2px;
}

.employee-satisfaction-fill {
  height: 100%;
  border-radius: 2px;
}

/* 产品运营数据 */
.product-ops-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-top: 8px;
}

.product-ops-stat {
  padding: 8px;
  background: var(--bg-secondary);
  border-radius: 4px;
  text-align: center;
}

.product-ops-stat-label {
  font-size: 10px;
  color: var(--text-muted);
}

.product-ops-stat-value {
  font-size: 14px;
  font-weight: bold;
  color: var(--text-primary);
  margin-top: 2px;
}

