    desc: `名气${fame}点，商家请你站台推广，收现金并涨粉。(每天一次)`,
    ap: 15,
    handler: () => {
      var earn = 50 + Math.floor(fame * 1.2) + Random.int(0, 79);
      state.resources.cash += earn;
      state.resources.totalEarned += earn;
