      state.player.fame = Math.min(100, state.player.fame + 3);
      state.flags._fameVipUsedToday = state.flags._fameVipUsedToday || {};
      state.flags._fameVipUsedToday.commercialVip = true;
      consumeAP(15);
      StateManager.addMessage(
        "🌟 你在商业街露了个脸，路人纷纷拍照！获得¥" +
          earn +
          "，名气+3。",
